mapper.update:
UPDATE ainer_identity_notification_outbox
SET publication_status = 'FAILED',
    available_at = #{availableAt},
    lease_owner = NULL,
    lease_until = NULL,
    last_error_code = #{errorCode}
WHERE id = #{notificationId}
  AND lease_owner = #{leaseOwner}
  AND publication_status IN ('PENDING', 'FAILED')

mapper.select:
SELECT count(*) FILTER (
           WHERE publication_status = 'PENDING'
             AND attempt_count < #{maxAttempts}
       ) AS pending,
       count(*) FILTER (
           WHERE publication_status = 'FAILED'
             AND attempt_count < #{maxAttempts}
       ) AS failed,
       count(*) FILTER (
           WHERE publication_status IN ('PENDING', 'FAILED')
             AND attempt_count >= #{maxAttempts}
       ) AS exhausted,
       count(*) FILTER (WHERE publication_status = 'PUBLISHED') AS published,
       count(*) FILTER (WHERE publication_status = 'CANCELLED') AS cancelled,
       min(available_at) FILTER (
           WHERE publication_status IN ('PENDING', 'FAILED')
             AND attempt_count < #{maxAttempts}
       ) AS oldest_ready_at
FROM ainer_identity_notification_outbox
